//! Mandatory offline #224 VLLE/LLE checks against independent Clapeyron.jl
//! references (`validation/fixtures/vlle-v1.json`, generated by
//! `validation/julia/generate_vlle.jl`). The live check supplies a fresh
//! candidate through THERMO_VLLE_REFERENCE without replacing the fixture.
mod common;

use serde_json::Value;
use thermo_data::{AlphaTerms, ComponentDatabase, LiquidDatabase, TauTerms};
use thermo_models::{ActivityModel, CubicModel, CubicVariant, NrtlParameters, VaporModel};
use thermo_solvers::{
    MultiphaseOptions, MultiphasePhase, activity_vlle_ph_flash, activity_vlle_tp_flash,
    vlle_ph_flash, vlle_tp_flash,
};
use thermo_types::{
    ComponentId, Composition, CompositionBasis, NormalizationPolicy, Phase, Pressure, Temperature,
};

const INPUTS: &str = include_str!("../../../validation/vlle-inputs.json");

fn fixture() -> Value {
    let input = match std::env::var_os("THERMO_VLLE_REFERENCE") {
        Some(path) => std::fs::read_to_string(path).expect("read live VLLE candidate"),
        None => include_str!("../../../validation/fixtures/vlle-v1.json").into(),
    };
    let f: Value = serde_json::from_str(&input).expect("valid VLLE reference JSON");
    assert_eq!(f["schema"], "vlle-clapeyron-v1");
    assert_eq!(f["clapeyron_version"], "0.6.30");
    assert_eq!(f["julia_version"], "1.11.7");
    common::assert_input_hashes("vlle-v1.json", &f);
    for (key, count) in [
        ("cubic_tp", 6),
        ("nrtl_tp", 5),
        ("cubic_ph_invariant", 1),
        ("nrtl_ph_invariant", 1),
    ] {
        assert_eq!(f[key].as_array().unwrap().len(), count, "{key} count");
    }
    f
}

fn inputs() -> Value {
    serde_json::from_str(INPUTS).unwrap()
}

fn numbers(v: &Value) -> Vec<f64> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_f64().unwrap())
        .collect()
}

fn strings(v: &Value) -> Vec<String> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_str().unwrap().to_string())
        .collect()
}

fn number(v: &Value) -> f64 {
    v.as_f64().unwrap()
}

thread_local! {
    static WORST: std::cell::RefCell<std::collections::BTreeMap<String, f64>> =
        const { std::cell::RefCell::new(std::collections::BTreeMap::new()) };
}

fn report(test: &str) {
    WORST.with(|w| {
        for (key, dev) in w.borrow_mut().split_off("") {
            println!("{test}: {key}: max |deviation| {dev:e}");
        }
    });
}

fn close(f: &Value, key: &str, actual: f64, expected: f64, context: &str) {
    let b = numbers(&f["tolerances"][key]);
    let limit = b[0] + b[1] * expected.abs();
    let dev = (actual - expected).abs();
    WORST.with(|w| {
        let mut w = w.borrow_mut();
        let e = w.entry(key.into()).or_insert(0.0);
        *e = e.max(dev);
    });
    assert!(
        actual.is_finite() && expected.is_finite() && dev <= limit,
        "{context}: {key}: Rust {actual:e}, Clapeyron {expected:e}, deviation {dev:e}, budget {limit:e}"
    );
}

fn close_all(f: &Value, key: &str, actual: &[f64], expected: &[f64], context: &str) {
    assert_eq!(actual.len(), expected.len(), "{context}: {key} length");
    for (a, e) in actual.iter().zip(expected) {
        close(f, key, *a, *e, context);
    }
}

fn composition(ids: &[String], z: &[f64]) -> Composition {
    Composition::new(
        CompositionBasis::Mole,
        ids.iter()
            .zip(z)
            .map(|(id, x)| (ComponentId::new(id.as_str()).unwrap(), *x))
            .collect(),
        NormalizationPolicy::RequireUnitSum,
    )
    .unwrap()
}

fn cubic(case: &Value) -> CubicModel {
    let variant = match case["variant"].as_str().unwrap() {
        "PR" => CubicVariant::PengRobinson,
        "PR-BM" => CubicVariant::PengRobinsonBostonMathias,
        other => panic!("unknown variant {other}"),
    };
    let ids = strings(&case["ids"]);
    let kij = case["kij"]
        .as_array()
        .unwrap()
        .iter()
        .map(numbers)
        .collect();
    CubicModel::new(
        &ComponentDatabase::embedded().unwrap(),
        &composition(&ids, &numbers(&case["z"])),
        variant,
        kij,
        "explicit water-hydrocarbon kij 0.5 (VLLE verification approximation)",
    )
    .unwrap()
}

fn nrtl(z: &[f64]) -> ActivityModel {
    let i = inputs();
    let p = &i["nrtl"];
    let ids = strings(&p["ids"]);
    let tau = |t1: f64| TauTerms {
        t0: 0.0,
        t1,
        t2: 0.0,
        t3: 0.0,
    };
    let alpha = AlphaTerms {
        a0: number(&p["alpha"]),
        a1: 0.0,
    };
    let none = AlphaTerms { a0: 0.0, a1: 0.0 };
    let parameters = NrtlParameters::new(
        ids.iter()
            .map(|i| ComponentId::new(i.as_str()).unwrap())
            .collect(),
        vec![
            vec![tau(0.0), tau(number(&p["b12_K"]))],
            vec![tau(number(&p["b21_K"])), tau(0.0)],
        ],
        vec![vec![none, alpha], vec![alpha, none]],
        p["note"].as_str().unwrap(),
    )
    .unwrap();
    ActivityModel::new(
        &ComponentDatabase::embedded().unwrap(),
        &LiquidDatabase::embedded().unwrap(),
        &composition(&ids, z),
        VaporModel::IdealGas,
        parameters,
    )
    .unwrap()
}

/// Per-phase view shared by both state types.
struct View {
    phase: Phase,
    fraction: f64,
    composition: Vec<f64>,
    molar_volume: f64,
    mass_density: f64,
    h: f64,
    ln_phi: Vec<f64>,
}

fn cubic_views(phases: &[MultiphasePhase<thermo_models::HomogeneousState>]) -> Vec<View> {
    phases
        .iter()
        .map(|p| View {
            phase: p.phase,
            fraction: p.phase_fraction,
            composition: p.composition.clone(),
            molar_volume: p.state.molar_volume,
            mass_density: p.state.mass_density,
            h: p.state.enthalpy,
            ln_phi: p.state.ln_fugacity_coefficients.clone(),
        })
        .collect()
}

fn activity_views(phases: &[MultiphasePhase<thermo_models::ActivityPhaseState>]) -> Vec<View> {
    phases
        .iter()
        .map(|p| View {
            phase: p.phase,
            fraction: p.phase_fraction,
            composition: p.composition.clone(),
            molar_volume: p.state.molar_volume,
            mass_density: p.state.mass_density,
            h: p.state.enthalpy,
            ln_phi: p.state.ln_fugacity_coefficients.clone(),
        })
        .collect()
}

/// Phase count, order, labels, amounts, compositions and phase properties.
fn compare_phases(f: &Value, actual: &[View], expected: &Value, context: &str) {
    let expected = expected.as_array().unwrap();
    assert_eq!(actual.len(), expected.len(), "{context}: phase count");
    for (k, (a, e)) in actual.iter().zip(expected).enumerate() {
        let c = format!("{context} phase {k}");
        let label = e
            .get("kind")
            .or_else(|| e.get("clapeyron_phase"))
            .and_then(Value::as_str);
        if let Some(label) = label {
            let vapor = label == "vapour";
            assert_eq!(a.phase == Phase::Vapor, vapor, "{c}: label {label}");
        }
        close(f, "fraction", a.fraction, number(&e["fraction"]), &c);
        close_all(
            f,
            "composition",
            &a.composition,
            &numbers(&e["composition"]),
            &c,
        );
        let s = &e["state"];
        close(
            f,
            "molar_volume",
            a.molar_volume,
            number(&s["molar_volume"]),
            &c,
        );
        close(
            f,
            "mass_density",
            a.mass_density,
            number(&s["mass_density"]),
            &c,
        );
        close(f, "h", a.h, number(&s["h"]), &c);
        close_all(f, "ln_phi", &a.ln_phi, &numbers(&s["ln_phi"]), &c);
    }
}

fn tp(t: f64, p: f64) -> (Temperature, Pressure) {
    (Temperature::new(t).unwrap(), Pressure::new(p).unwrap())
}

fn residual_bound(f: &Value) -> f64 {
    numbers(&f["tolerances"]["fugacity_residual"])[0]
}

#[test]
fn cubic_water_hydrocarbon_tp_matches_clapeyron() {
    let f = fixture();
    for case in f["cubic_tp"].as_array().unwrap() {
        let id = case["id"].as_str().unwrap();
        let (t, p) = tp(number(&case["T"]), number(&case["p"]));
        let r = vlle_tp_flash(&cubic(case), t, p, MultiphaseOptions::default())
            .unwrap_or_else(|e| panic!("{id}: {e}"));
        assert!(r.max_ln_fugacity_residual <= residual_bound(&f), "{id}");
        compare_phases(&f, &cubic_views(&r.phases), &case["phases"], id);
    }
    report("cubic_water_hydrocarbon_tp_matches_clapeyron");
}

#[test]
fn nrtl_partially_miscible_tp_matches_clapeyron() {
    let f = fixture();
    for case in f["nrtl_tp"].as_array().unwrap() {
        let id = case["id"].as_str().unwrap();
        let (t, p) = tp(number(&case["T"]), number(&case["p"]));
        let r = activity_vlle_tp_flash(
            &nrtl(&numbers(&case["z"])),
            t,
            p,
            MultiphaseOptions::default(),
        )
        .unwrap_or_else(|e| panic!("{id}: {e}"));
        assert!(r.max_ln_fugacity_residual <= residual_bound(&f), "{id}");
        compare_phases(&f, &activity_views(&r.phases), &case["phases"], id);
    }
    report("nrtl_partially_miscible_tp_matches_clapeyron");
}

fn activity_options() -> MultiphaseOptions {
    let [lo, hi] = thermo_models::ACTIVITY_TEMPERATURE_RANGE_K;
    MultiphaseOptions {
        minimum_temperature_k: lo,
        maximum_temperature_k: hi,
        ..Default::default()
    }
}

#[test]
fn ph_round_trips_reproduce_clapeyron_tp_states() {
    let f = fixture();
    let i = inputs();
    let find = |key: &str, id: &str| -> Value {
        f[key]
            .as_array()
            .unwrap()
            .iter()
            .find(|c| c["id"] == id)
            .unwrap_or_else(|| panic!("{id} missing"))
            .clone()
    };
    for id in strings(&i["cubic_ph_round_trip"]) {
        let case = find("cubic_tp", &id);
        let p = Pressure::new(number(&case["p"])).unwrap();
        let r = vlle_ph_flash(
            &cubic(&case),
            p,
            number(&case["h"]),
            MultiphaseOptions::default(),
        )
        .unwrap_or_else(|e| panic!("{id}: {e}"));
        close(&f, "temperature", r.temperature_k, number(&case["T"]), &id);
        assert!(r.scaled_energy_residual.abs() <= 1e-10, "{id}");
        compare_phases(&f, &cubic_views(&r.phases), &case["phases"], &id);
    }
    for id in strings(&i["nrtl_ph_round_trip"]) {
        let case = find("nrtl_tp", &id);
        let p = Pressure::new(number(&case["p"])).unwrap();
        let r = activity_vlle_ph_flash(
            &nrtl(&numbers(&case["z"])),
            p,
            number(&case["h"]),
            activity_options(),
        )
        .unwrap_or_else(|e| panic!("{id}: {e}"));
        close(&f, "temperature", r.temperature_k, number(&case["T"]), &id);
        compare_phases(&f, &activity_views(&r.phases), &case["phases"], &id);
    }
    report("ph_round_trips_reproduce_clapeyron_tp_states");
}

#[test]
fn ph_at_binary_three_phase_temperature_matches_clapeyron() {
    let f = fixture();
    for case in f["cubic_ph_invariant"].as_array().unwrap() {
        let id = case["id"].as_str().unwrap();
        let p = Pressure::new(number(&case["p"])).unwrap();
        let r = vlle_ph_flash(
            &cubic(case),
            p,
            number(&case["target_h"]),
            MultiphaseOptions::default(),
        )
        .unwrap_or_else(|e| panic!("{id}: {e}"));
        assert!(r.invariant_temperature, "{id}");
        assert!(r.max_ln_fugacity_residual <= residual_bound(&f), "{id}");
        close(&f, "temperature", r.temperature_k, number(&case["T"]), id);
        compare_phases(&f, &cubic_views(&r.phases), &case["phases"], id);
    }
    for case in f["nrtl_ph_invariant"].as_array().unwrap() {
        let id = case["id"].as_str().unwrap();
        let p = Pressure::new(number(&case["p"])).unwrap();
        let r = activity_vlle_ph_flash(
            &nrtl(&numbers(&case["z"])),
            p,
            number(&case["target_h"]),
            activity_options(),
        )
        .unwrap_or_else(|e| panic!("{id}: {e}"));
        assert!(r.invariant_temperature, "{id}");
        assert!(r.max_ln_fugacity_residual <= residual_bound(&f), "{id}");
        close(&f, "temperature", r.temperature_k, number(&case["T"]), id);
        compare_phases(&f, &activity_views(&r.phases), &case["phases"], id);
    }
    report("ph_at_binary_three_phase_temperature_matches_clapeyron");
}
